import{az as a,P as n,Q as l,aQ as t}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const F=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"server/数据库/index.md","filePath":"server/数据库/index.md","lastUpdated":1785339991000}'),p={name:"server/数据库/index.md"};function o(e,s,c,r,y,i){return n(),l("div",null,[...s[0]||(s[0]=[t(`<h2 id="数据库概述" tabindex="-1">数据库概述 <a class="header-anchor" href="#数据库概述" aria-label="Permalink to “数据库概述”">​</a></h2><p><a href="https://developer.mozilla.org/zh-CN/docs/Glossary/Database" target="_blank" rel="noreferrer">数据库基础概念</a></p><p>数据库是按照数据结构来组织、存储和管理数据的仓库。在 Web 应用中，数据库负责持久化存储用户数据、业务记录等核心信息。根据数据模型的不同，数据库主要分为关系型与非关系型两大类。</p><h2 id="关系型数据库-rdbms" tabindex="-1">关系型数据库（RDBMS） <a class="header-anchor" href="#关系型数据库-rdbms" aria-label="Permalink to “关系型数据库（RDBMS）”">​</a></h2><p>关系型数据库以表格形式存储数据，表与表之间通过关系（外键）关联。使用 SQL（Structured Query Language）进行操作，支持事务和复杂的关联查询。</p><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">-- 用户表</span></span>
<span class="line"><span style="color:#F78C6C;">CREATE</span><span style="color:#F78C6C;"> TABLE</span><span style="color:#82AAFF;"> users</span><span style="color:#BABED8;"> (</span></span>
<span class="line"><span style="color:#BABED8;">  id </span><span style="color:#C792EA;">INT</span><span style="color:#C792EA;"> PRIMARY KEY</span><span style="color:#BABED8;"> AUTO_INCREMENT,</span></span>
<span class="line"><span style="color:#F78C6C;">  name</span><span style="color:#C792EA;"> VARCHAR</span><span style="color:#BABED8;">(</span><span style="color:#F78C6C;">50</span><span style="color:#BABED8;">) </span><span style="color:#F78C6C;">NOT NULL</span><span style="color:#BABED8;">,</span></span>
<span class="line"><span style="color:#BABED8;">  email </span><span style="color:#C792EA;">VARCHAR</span><span style="color:#BABED8;">(</span><span style="color:#F78C6C;">100</span><span style="color:#BABED8;">) </span><span style="color:#F78C6C;">UNIQUE</span></span>
<span class="line"><span style="color:#BABED8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">-- 订单表，通过 user_id 关联用户</span></span>
<span class="line"><span style="color:#F78C6C;">CREATE</span><span style="color:#F78C6C;"> TABLE</span><span style="color:#82AAFF;"> orders</span><span style="color:#BABED8;"> (</span></span>
<span class="line"><span style="color:#BABED8;">  id </span><span style="color:#C792EA;">INT</span><span style="color:#C792EA;"> PRIMARY KEY</span><span style="color:#BABED8;"> AUTO_INCREMENT,</span></span>
<span class="line"><span style="color:#BABED8;">  user_id </span><span style="color:#C792EA;">INT</span><span style="color:#BABED8;">,</span></span>
<span class="line"><span style="color:#BABED8;">  amount </span><span style="color:#C792EA;">DECIMAL</span><span style="color:#BABED8;">(</span><span style="color:#F78C6C;">10</span><span style="color:#BABED8;">, </span><span style="color:#F78C6C;">2</span><span style="color:#BABED8;">),</span></span>
<span class="line"><span style="color:#C792EA;">  FOREIGN KEY</span><span style="color:#BABED8;"> (user_id) </span><span style="color:#C792EA;">REFERENCES</span><span style="color:#BABED8;"> users(id)</span></span>
<span class="line"><span style="color:#BABED8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">-- 关联查询</span></span>
<span class="line"><span style="color:#F78C6C;">SELECT</span><span style="color:#BABED8;"> u.name, o.amount</span></span>
<span class="line"><span style="color:#F78C6C;">FROM</span><span style="color:#BABED8;"> users u</span></span>
<span class="line"><span style="color:#F78C6C;">JOIN</span><span style="color:#BABED8;"> orders o </span><span style="color:#F78C6C;">ON</span><span style="color:#BABED8;"> u.id </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> o.user_id;</span></span></code></pre></div><h2 id="非关系型数据库-nosql" tabindex="-1">非关系型数据库（NoSQL） <a class="header-anchor" href="#非关系型数据库-nosql" aria-label="Permalink to “非关系型数据库（NoSQL）”">​</a></h2><p>非关系型数据库不使用传统的表格模型，数据结构灵活，适合海量数据和高并发场景。</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">// MongoDB 文档型数据库示例</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">// 数据以 JSON-like 文档存储，无需预定义表结构</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">db</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">users</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">insertOne</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#F07178;">  name</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">Alice</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#F07178;">  email</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">alice@example.com</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#F07178;">  preferences</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span><span style="color:#F07178;"> theme</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">dark</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span><span style="color:#F07178;"> lang</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">zh</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;"> },</span></span>
<span class="line"><span style="color:#F07178;">  tags</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> [</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">vip</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">active</span><span style="color:#89DDFF;">&#39;</span><span style="color:#BABED8;">]</span></span>
<span class="line"><span style="color:#89DDFF;">}</span><span style="color:#BABED8;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">db</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">users</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">find</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">{</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#F07178;">preferences.theme</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">dark</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;"> }</span><span style="color:#BABED8;">)</span><span style="color:#89DDFF;">;</span></span></code></pre></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># Redis 键值型数据库示例</span></span>
<span class="line"><span style="color:#FFCB6B;">SET</span><span style="color:#C3E88D;"> user:1:name</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">Alice</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#FFCB6B;">GET</span><span style="color:#C3E88D;"> user:1:name</span></span>
<span class="line"><span style="color:#FFCB6B;">HSET</span><span style="color:#C3E88D;"> user:1</span><span style="color:#C3E88D;"> email</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">alice@example.com</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;"> age</span><span style="color:#F78C6C;"> 30</span></span>
<span class="line"><span style="color:#FFCB6B;">HGETALL</span><span style="color:#C3E88D;"> user:1</span></span></code></pre></div><h2 id="关系型-vs-非关系型" tabindex="-1">关系型 vs 非关系型 <a class="header-anchor" href="#关系型-vs-非关系型" aria-label="Permalink to “关系型 vs 非关系型”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>关系型（SQL）</th><th>非关系型（NoSQL）</th></tr></thead><tbody><tr><td>数据结构</td><td>表格（行与列）</td><td>文档/键值/列族/图</td></tr><tr><td>查询语言</td><td>SQL</td><td>各自的 API</td></tr><tr><td>Schema</td><td>固定，预定义</td><td>灵活，动态</td></tr><tr><td>事务</td><td>ACID 强事务</td><td>最终一致性为主</td></tr><tr><td>关联查询</td><td>强（JOIN）</td><td>弱或不支持</td></tr><tr><td>扩展方式</td><td>垂直扩展为主</td><td>水平扩展友好</td></tr><tr><td>典型产品</td><td>MySQL、PostgreSQL</td><td>MongoDB、Redis、Cassandra</td></tr></tbody></table><h2 id="acid-事务特性" tabindex="-1">ACID 事务特性 <a class="header-anchor" href="#acid-事务特性" aria-label="Permalink to “ACID 事务特性”">​</a></h2><p>关系型数据库的事务遵循 ACID 原则：</p><table tabindex="0"><thead><tr><th>特性</th><th>含义</th><th>说明</th></tr></thead><tbody><tr><td>原子性（Atomicity）</td><td>事务要么全部成功，要么全部回滚</td><td>转账扣款与加款必须同时成功</td></tr><tr><td>一致性（Consistency）</td><td>事务前后数据保持一致</td><td>金额总和不变</td></tr><tr><td>隔离性（Isolation）</td><td>并发事务互不干扰</td><td>两人同时转账不冲突</td></tr><tr><td>持久性（Durability）</td><td>事务提交后永久保存</td><td>断电不丢失</td></tr></tbody></table><div class="language-sql"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;">-- 事务示例：转账</span></span>
<span class="line"><span style="color:#F78C6C;">START TRANSACTION</span><span style="color:#BABED8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F78C6C;">UPDATE</span><span style="color:#BABED8;"> accounts </span><span style="color:#F78C6C;">SET</span><span style="color:#BABED8;"> balance </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> balance </span><span style="color:#89DDFF;">-</span><span style="color:#F78C6C;"> 100</span><span style="color:#F78C6C;"> WHERE</span><span style="color:#BABED8;"> id </span><span style="color:#89DDFF;">=</span><span style="color:#F78C6C;"> 1</span><span style="color:#BABED8;">;  </span><span style="color:#676E95;font-style:italic;">-- 扣款</span></span>
<span class="line"><span style="color:#F78C6C;">UPDATE</span><span style="color:#BABED8;"> accounts </span><span style="color:#F78C6C;">SET</span><span style="color:#BABED8;"> balance </span><span style="color:#89DDFF;">=</span><span style="color:#BABED8;"> balance </span><span style="color:#89DDFF;">+</span><span style="color:#F78C6C;"> 100</span><span style="color:#F78C6C;"> WHERE</span><span style="color:#BABED8;"> id </span><span style="color:#89DDFF;">=</span><span style="color:#F78C6C;"> 2</span><span style="color:#BABED8;">;  </span><span style="color:#676E95;font-style:italic;">-- 加款</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;">-- 任一步骤失败则回滚</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">-- 全部成功则提交</span></span>
<span class="line"><span style="color:#F78C6C;">COMMIT</span><span style="color:#BABED8;">;</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">-- ROLLBACK;</span></span></code></pre></div><h2 id="cap-定理" tabindex="-1">CAP 定理 <a class="header-anchor" href="#cap-定理" aria-label="Permalink to “CAP 定理”">​</a></h2><p>分布式系统无法同时满足以下三个特性：</p><table tabindex="0"><thead><tr><th>特性</th><th>含义</th></tr></thead><tbody><tr><td>一致性（Consistency）</td><td>所有节点数据一致</td></tr><tr><td>可用性（Availability）</td><td>每个请求都能收到响应</td></tr><tr><td>分区容错性（Partition tolerance）</td><td>网络分区时仍能运行</td></tr></tbody></table><table tabindex="0"><thead><tr><th>数据库类型</th><th>取舍</th><th>适用场景</th></tr></thead><tbody><tr><td>CP</td><td>一致性 + 分区容错</td><td>金融系统</td></tr><tr><td>AP</td><td>可用性 + 分区容错</td><td>社交网络、缓存</td></tr></tbody></table><h2 id="选型建议" tabindex="-1">选型建议 <a class="header-anchor" href="#选型建议" aria-label="Permalink to “选型建议”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 关系型数据库适合：</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - 数据结构固定，关系明确</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - 需要强事务保证（如金融）</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - 复杂的关联查询</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 非关系型数据库适合：</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - 数据结构灵活，频繁变更</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - 海量数据高并发读写</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - 缓存、日志、实时数据</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 混合使用是常见实践：</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - MySQL 存核心业务数据</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - Redis 做缓存与会话</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - Elasticsearch 做全文搜索</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># - MongoDB 存日志与非结构化数据</span></span></code></pre></div><p>数据库选型没有银弹，需要根据业务特点在一致性、可用性、性能之间权衡。实际项目中，多种数据库配合使用是常态。</p>`,23)])])}const E=a(p,[["render",o]]);export{F as __pageData,E as default};
